-- Ruins of Ahn'Qiraj: the Classic armor, jewelry, cloaks, shields and off-hands that drop there had no item row
-- (the WoW Forever client blanks them), so every one was an invalid loot item and nothing dropped. Rows from the
-- Classic item data: stats as budget shares, armor from the item level formula, Classic sell prices, Classic
-- equip and use spells as item effects, hotfix_data so the client shows them.
DELETE FROM `item_sparse` WHERE `ID` IN (21453,21454,21455,21456,21457,21458,21460,21461,21462,21463,21464,21467,21468,21469,21470,21471,21472,21474,21475,21476,21479,21480,21481,21482,21484,21485,21486,21487,21489,21490,21491,21493,21494,21495,21496,21497,21499,21500,21501,21502,21503,21803,21804,21805,21810);
DELETE FROM `item_effect` WHERE `ID` BETWEEN 9900586 AND 9900638;
DELETE FROM `item_x_item_effect` WHERE `ID` BETWEEN 9900586 AND 9900638;
DELETE FROM `hotfix_data` WHERE `Id` BETWEEN 26112957 AND 26113107;
